(() => {
  const meta = (sel) => { const el = document.querySelector(sel); return el ? (el.getAttribute('content') || '') : ''; };
  const pick = (...sels) => {
    for (const s of sels) {
      const el = document.querySelector(s);
      if (el && el.innerText && el.innerText.trim().length > 40) return el.innerText.trim();
    }
    return '';
  };
  const body = document.body ? document.body.innerText : '';
  return JSON.stringify({
    url: location.href,
    title: document.title,
    ogTitle: meta('meta[property="og:title"]'),
    ogDescription: meta('meta[property="og:description"]'),
    ogSite: meta('meta[property="og:site_name"]'),
    author: meta('meta[name="author"]') || meta('meta[property="article:author"]'),
    published: meta('meta[property="article:published_time"]'),
    text: (pick('article', 'main', '[role="main"]') || body).slice(0, 8000)
  });
})()
